import pdfplumber
import json

invoices = []

with pdfplumber.open("/root/invoices.pdf") as pdf:
    for page_num, page in enumerate(pdf.pages, 1):
        text = page.extract_text()

        invoice_data = {
            "page": page_num,
            "vendor_name": None,
            "invoice_amount": None,
            "iban": None,
            "po_number": None
        }

        lines = text.split('\n') if text else []

        for i, line in enumerate(lines):
            line_upper = line.upper()

            if 'FROM:' in line_upper or 'VENDOR' in line_upper:
                parts = line.split(':', 1)
                if len(parts) > 1:
                    invoice_data["vendor_name"] = parts[1].strip()

            if 'TOTAL' in line_upper and '$' in line:
                import re
                matches = re.findall(r'\$[\d,.]+', line)
                if matches:
                    cleaned = matches[0].replace('$', '').replace(',', '')
                    try:
                        invoice_data["invoice_amount"] = float(cleaned)
                    except:
                        pass

            if 'IBAN:' in line_upper:
                parts = line.split(':', 1)
                if len(parts) > 1:
                    invoice_data["iban"] = parts[1].strip()

            if 'PO NUMBER:' in line_upper or 'PO#' in line_upper:
                parts = line.split(':', 1)
                if len(parts) > 1:
                    po = parts[1].strip()
                    invoice_data["po_number"] = po

        invoices.append(invoice_data)

print(json.dumps(invoices, indent=2))
